public sealed class HardwareModuleName
{
    public Asn1Oid HwType { get; set; }
    public ReadOnlyMemory<byte> HwSerialNum { get; set; }

    public void Encode(Asn1Writer writer) => Encode(writer, DefaultTag);

    public void Encode(Asn1Writer writer, Asn1Tag tag)
    {
        using (writer.EnterSequence(tag))
        {
            writer.WriteObjectIdentifier(Asn1Tag.ObjectIdentifier, HwType);
            writer.WriteOctetString(Asn1Tag.OctetString, HwSerialNum.Span);
        }
    }

    public static HardwareModuleName Decode(Asn1Reader reader) => Decode(reader, DefaultTag);

    public static HardwareModuleName Decode(Asn1Reader reader, Asn1Tag tag)
    {
        using (reader.EnterSequence(tag))
        {
            var value = new HardwareModuleName();
            value.HwType = reader.ReadOid(Asn1Tag.ObjectIdentifier);
            value.HwSerialNum = reader.ReadOctetString(Asn1Tag.OctetString);
            reader.ThrowIfNotEmpty();
            return value;
        }
    }

    public static Asn1Tag DefaultTag { get; } = Asn1Tag.Sequence;
}

